<script lang="ts">
 import {onMount,onDestroy} from 'svelte';
 import {surface} from './surfaces';
 import type {BoardControls} from '../plugins/interface';
 import {tasksAt,taskHistory,type NoteTask} from '../core/tasks';
 import type {Atom,Snapshot,AtomState} from '../core/model';
 import type {Core} from '../core/core';
 let {data,core,onopen,options}:{data:Snapshot;core:Core;onopen:(id:string)=>void;options:BoardControls|null}=$props();
 let recurrence=$state<{atomId:string;taskId:string;x:number;y:number}|null>(null);
 function showRecurrence(e:MouseEvent,atom:Atom,task:NoteTask){const box=(e.currentTarget as HTMLElement).getBoundingClientRect();recurrence={atomId:atom.id,taskId:task.id,x:Math.max(12,Math.min(box.right-270,window.innerWidth-282)),y:Math.max(12,Math.min(box.bottom+6,window.innerHeight-330))};}
 let clock=$state(Date.now());onMount(()=>{const timer=setInterval(()=>clock=Date.now(),60000);return()=>clearInterval(timer);});
 const lanes=[['now','Сейчас'],['normal','Поле'],['archived','Архив']] as const;
 let archiveOffer=$state('');let busy=$state(false),error=$state(''),drag=$state<{id:string;title:string;pointer:number;lane:string;x:number;y:number}|null>(null),period=$state(7);
 let deletion=$state<{before:Atom;revision:number}|null>(null);let undoTimer:ReturnType<typeof setTimeout>;onDestroy(()=>clearTimeout(undoTimer));
 const groups=$derived(data.atoms.map(atom=>({atom,tasks:tasksAt(atom,new Date(clock))})).filter(group=>group.tasks.length));
 const recurrenceGroup=$derived(groups.find(g=>g.atom.id===recurrence?.atomId));
 const recurrenceTask=$derived(recurrenceGroup?.tasks.find(t=>t.id===recurrence?.taskId));
 async function run(fn:()=>Promise<unknown>){if(busy)return;busy=true;error='';try{await fn();}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function removeTask(atom:Atom,task:NoteTask){await run(async()=>{const before=structuredClone($state.snapshot(atom)),saved=await core.setTask(atom.id,task.id,{remove:true});deletion={before,revision:saved.revision};clearTimeout(undoTimer);undoTimer=setTimeout(()=>deletion=null,3800);});}
 async function undoTask(){if(!deletion)return;const saved=deletion;await run(async()=>{await core.update(saved.before.id,{content:saved.before.content,properties:saved.before.properties},saved.revision);deletion=null;clearTimeout(undoTimer);});}
 function history(task:NoteTask){return taskHistory(task,period as 7|30,new Date(clock));}
 async function toggle(atom:Atom,task:NoteTask,checked:boolean){await run(async()=>{await core.setTask(atom.id,task.id,{checked});const saved=core.data.atoms.find(a=>a.id===atom.id);if(checked&&saved&&saved.state!=='archived'&&tasksAt(saved).every(t=>t.checked)&&tasksAt(saved).every(t=>!t.recurrence))archiveOffer=atom.id;});}
 function completed(task:NoteTask){return history(task).filter(day=>day.completed).length;}
 function begin(e:PointerEvent,atom:Atom){if(busy||e.button!==0)return;e.preventDefault();(e.currentTarget as HTMLElement).focus({preventScroll:true});(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);drag={id:atom.id,title:atom.title,pointer:e.pointerId,lane:'',x:e.clientX,y:e.clientY};}
 function move(e:PointerEvent){if(!drag||e.pointerId!==drag.pointer)return;const lane=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-task-lane]')?.getAttribute('data-task-lane')||'';drag={...drag,lane,x:e.clientX,y:e.clientY};}
 function end(e:PointerEvent){if(!drag||e.pointerId!==drag.pointer)return;move(e);const value=drag;drag=null;if(value?.lane)void run(()=>core.setState(value.id,value.lane as AtomState));}
</script>
<svelte:window onkeydown={e=>{if(e.key==='Escape')drag=null;}} onpointerdown={e=>{if(drag&&e.pointerId!==drag.pointer)drag=null;}}/>
<section style={`--board-scale:${options?.scale??.9};--board-gap:${options?.gap??6}px`} class="kanban" aria-label="Канбан">
 <div class="board-heading"><div><small>ЗАДАЧИ ВАШИХ АТОМОВ</small><h1>Канбан</h1></div><span>{groups.reduce((n,g)=>n+g.tasks.filter(t=>!t.checked).length,0)} незавершённых</span></div>
 {#if error}<p role="alert">{error}<button onclick={()=>error=''}>Закрыть</button></p>{/if}
 {#if deletion}<div class="task-undo" role="status"><span>Задача удалена</span><button disabled={busy} onclick={undoTask}>Отменить удаление задачи</button></div>{/if}
 {#if drag}<div class="task-drag-preview" aria-hidden="true" style:left={`${Math.max(16,Math.min(drag.x-110,window.innerWidth-236))}px`} style:top={`${Math.max(12,drag.y-76)}px`}><span>&#8942;&#8942;</span><strong>{drag.title}</strong></div><div class="task-destinations" aria-label="Куда переместить"><strong>{drag.title}</strong><div>{#each lanes as [state,label]}<button data-task-lane={state} class:active={drag.lane===state}>{label}</button>{/each}</div></div>{/if}
 {#snippet group(atom:Atom,tasks:NoteTask[],paused=false)}
 <article class="task-group" class:drag-source={drag?.id===atom.id} data-source={atom.id}>
 <div class="group-heading"><button class="group-title" onclick={()=>onopen(atom.id)}>{atom.title}</button><button class="group-drag" aria-label={`Переместить группу ${atom.title}`} title="Перетяните в колонку" disabled={busy} onpointerdown={e=>begin(e,atom)} onpointermove={move} onpointerup={end} onpointercancel={()=>drag=null}>&#8942;&#8942;</button></div>
 <div class="group-controls"><select aria-label={`Состояние ${atom.title}`} value={atom.state} disabled={busy} onchange={e=>run(()=>core.setState(atom.id,e.currentTarget.value as AtomState))}>{#each lanes as [state,label]}<option value={state}>{label}</option>{/each}</select>{#if paused}<button disabled={busy} onclick={()=>run(()=>core.setPaused(atom.id,false))}>Возобновить</button>{/if}</div>
 {#each tasks as task (task.id)}
 <div class="board-task"><label><input type="checkbox" checked={task.checked} disabled={busy} aria-label={task.text} onchange={e=>toggle(atom,task,e.currentTarget.checked)}/><span class:done={task.checked}>{task.text}</span></label>
 <button class="task-repeat" class:repeating={Boolean(task.recurrence)} aria-label={`Повторение ${task.text}`} aria-haspopup="dialog" onclick={e=>showRecurrence(e,atom,task)}><svg viewBox="0 0 20 20" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M15 4l3 3-3 3M18 7H7a4 4 0 0 0-4 4M5 16l-3-3 3-3M2 13h11a4 4 0 0 0 4-4"/></svg></button>
 <button class="task-delete" disabled={busy} aria-label={`Удалить задачу ${task.text}`} onclick={()=>removeTask(atom,task)}><svg viewBox="0 0 20 20" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M4 5h12M8 5V3h4v2M6 5l1 12h6l1-12M9 8v6M11 8v6"/></svg></button>
 </div>{/each}
 </article>
 {/snippet}
 {#if archiveOffer}<div class="archive-offer" role="status"><span>Все задачи выполнены. Убрать мысль в архив?</span><button onclick={()=>run(async()=>{await core.setState(archiveOffer,'archived');archiveOffer='';})}>В архив</button><button onclick={()=>archiveOffer=''}>Оставить</button></div>{/if}
 {#if !groups.length}<div class="board-empty"><h2>Задачи живут в ваших мыслях</h2><p>В редакторе атома нажмите Task на панели инструментов или добавьте строку «- [ ] #task Купить билеты». Задачи появятся здесь группой. Обычные чекбоксы остаются в тексте.</p></div>{:else}<div class="board-lanes">{#each lanes as [state,label]}<section class="board-lane" class:drop-target={drag?.lane===state} data-task-lane={state} aria-label={label}><h2>{label}<small>{groups.filter(g=>!g.atom.paused&&g.atom.state===state).length}</small></h2>{#each groups.filter(g=>!g.atom.paused&&g.atom.state===state) as g (g.atom.id)}{@render group(g.atom,g.tasks)}{:else}<p class="lane-empty">Пока пусто</p>{/each}</section>{/each}</div>
 {@const paused=groups.filter(g=>g.atom.paused)}{#if paused.length}<details class="paused-groups"><summary>На паузе ({paused.length})</summary>{#each paused as g (g.atom.id)}{@render group(g.atom,g.tasks,true)}{/each}</details>{/if}{/if}
</section>
{#if recurrence&&recurrenceGroup&&recurrenceTask}
 {@const atom=recurrenceGroup.atom}{@const task=recurrenceTask}
 <div class="recurrence-popup" role="dialog" aria-label="Повторение задачи" use:surface={{close:()=>recurrence=null}} style:left={`${recurrence.x}px`} style:top={`${recurrence.y}px`}>
 <header><strong>{task.text}</strong><button aria-label="Закрыть" onclick={()=>recurrence=null}>×</button></header><label>Повторение <select aria-label={`Повтор ${task.text}`} value={task.recurrence||''} disabled={busy} onchange={e=>run(()=>core.setTask(atom.id,task.id,{recurrence:e.currentTarget.value as 'daily'|'weekly'||null}))}><option value="">Однократно</option><option value="daily">Ежедневно</option><option value="weekly">Еженедельно</option></select></label>{#if task.recurrence}<label>История <select aria-label={`Период ${task.text}`} bind:value={period}><option value={7}>7 дней</option><option value={30}>30 дней</option></select></label><div class="task-history" role="list" aria-label="История">{#each history(task) as day (day.key)}<span role="listitem" class:complete={day.completed} class:current={day.current} title={`${day.key}: ${day.completed?'✓':'—'}`} aria-label={`${day.key}: ${day.completed?'✓':'—'}`}>{day.completed?'✓':'·'}</span>{/each}</div><p>{completed(task)} выполнений за {period} дней</p>{/if}</div>
{/if}
<style>
 .task-undo{position:fixed;z-index:5;left:50%;bottom:calc(160px + env(safe-area-inset-bottom));transform:translateX(-50%);display:flex;align-items:center;gap:8px;width:max-content;max-width:calc(100vw - 24px);padding:6px 10px;border:1px solid var(--theme-border);border-radius:16px;background:var(--theme-surface);box-shadow:0 4px 18px #0002;font-size:12px}.task-undo button{font-size:11px;padding:4px 8px;min-height:36px}
 .task-drag-preview{position:fixed;z-index:30;pointer-events:none;display:flex;gap:12px;align-items:center;width:220px;padding:14px 16px;border:1px solid var(--theme-accent);border-radius:16px;background:var(--theme-surface);box-shadow:0 12px 32px #0004;transform:rotate(-2deg)}.task-drag-preview strong{font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.task-drag-preview span{color:var(--theme-muted)}.task-group.drag-source{opacity:.4}.board-lane.drop-target{outline:1px solid var(--theme-accent);outline-offset:8px;border-radius:12px}.group-drag{cursor:grab}.drag-source .group-drag{cursor:grabbing}
 .task-history{display:flex;flex-wrap:wrap;gap:4px;margin:12px 0}.task-history span{display:grid;place-items:center;width:24px;height:24px;border-radius:7px;background:var(--theme-background);color:var(--theme-muted);font-size:12px}.task-history .complete{background:var(--theme-accent);color:var(--theme-background)}.task-history .current{outline:1px solid var(--theme-muted);outline-offset:1px}
 .kanban{position:absolute;inset:90px 0 120px;z-index:2;overflow:auto;padding:20px clamp(16px,3vw,42px) 50px;background:var(--theme-background);overscroll-behavior:contain;animation:board-in .18s ease-out}.board-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:26px;gap:12px}.board-heading h1{font-size:30px;letter-spacing:-1px;margin:6px 0}.board-heading small,.board-heading>span{font-size:11px;color:var(--theme-muted)}.board-lanes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.board-lane{min-width:0}.board-lane h2{font-size:16px;font-weight:500;margin:0 0 14px;display:flex;justify-content:space-between;align-items:center}.board-lane h2 small{font-size:11px;color:var(--theme-muted)}.task-group{border:1px solid var(--theme-border);border-radius:20px;background:var(--theme-surface);padding:14px;margin-bottom:14px}.group-heading{display:flex;align-items:center;gap:6px}.group-title{border:0;background:none;text-align:left;font-weight:600;padding:6px 0;flex:1;min-width:0;overflow-wrap:anywhere}.group-drag{touch-action:none;padding:6px 10px;font-size:20px;border:0;background:none;min-width:44px}.group-controls{display:flex;gap:8px;margin:4px 0 12px}.group-controls select{font-size:11px;padding:6px 10px;flex:1;min-width:0}.group-controls button{font-size:11px;padding:6px 10px}.board-task{padding:8px 0}.board-task>label{display:flex;gap:10px;align-items:center;font-size:14px;line-height:1.5;overflow-wrap:anywhere}.board-task input{flex:0 0 24px;width:24px;height:24px;min-height:24px;accent-color:var(--theme-accent);cursor:pointer}.done{text-decoration:line-through;color:var(--theme-muted)}.lane-empty{font-size:12px;color:var(--theme-muted);padding:10px}.paused-groups{margin-top:30px}.paused-groups>.task-group{max-width:440px;opacity:.8}.board-empty{max-width:420px;margin:60px auto;text-align:center}.task-destinations{position:fixed;top:90px;left:50%;transform:translateX(-50%);z-index:20;max-width:95vw;padding:12px;border-radius:20px;background:var(--theme-surface);box-shadow:0 8px 40px #0006}.task-destinations strong{display:block;font-size:12px;max-width:280px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-bottom:8px}.task-destinations>div{display:flex;gap:5px}.task-destinations button{padding:8px;font-size:12px}@media(max-width:650px){.kanban{top:85px}.board-lanes{grid-template-columns:1fr;gap:28px}.board-heading{margin-bottom:20px}.task-destinations{top:80px}}@keyframes board-in{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}@media(prefers-reduced-motion:reduce){.kanban{animation:none}}
.task-group{border-radius:16px;padding:10px 12px;margin-bottom:10px}.group-controls{margin:2px 0 6px}.board-task{padding:4px 0}.board-heading{margin-bottom:16px}.board-heading h1{font-size:24px}.board-lanes{gap:12px}.archive-offer{display:flex;flex-wrap:wrap;gap:8px;align-items:center;border:1px solid var(--theme-border);border-radius:16px;padding:10px;margin-bottom:14px;background:var(--theme-surface)}.archive-offer span{flex:1;font-size:12px}

 .task-group{padding:calc(10px * var(--board-scale));margin-bottom:var(--board-gap)}.board-lanes{gap:calc(var(--board-gap) * 2)}.board-task{display:flex;align-items:center;gap:2px;padding:calc(var(--board-gap) / 3) 0}.board-task>label{flex:1;min-width:0;gap:8px;font-size:calc(14px * var(--board-scale));line-height:1.4;min-height:36px}.board-task input{flex:0 0 17px;width:17px;height:17px;min-height:17px}.task-repeat,.task-delete{display:grid;place-items:center;flex:none;width:36px;height:36px;min-height:36px;padding:0;border:0;background:transparent;color:var(--theme-muted);opacity:.65}.task-repeat.repeating{color:var(--theme-accent);opacity:1}.task-repeat:focus-visible,.task-delete:focus-visible{opacity:1}.recurrence-popup{position:fixed;width:270px;max-width:calc(100vw - 24px);max-height:calc(100dvh - 24px);overflow:auto;padding:14px;border:1px solid var(--theme-border);border-radius:18px;background:var(--theme-surface);box-shadow:0 12px 40px #0004}.recurrence-popup header{display:flex;gap:8px;align-items:center;margin-bottom:10px}.recurrence-popup strong{flex:1;min-width:0;overflow-wrap:anywhere;font-size:13px}.recurrence-popup header button{padding:4px 10px}.recurrence-popup label{display:flex;gap:8px;align-items:center;justify-content:space-between;margin:8px 0;font-size:12px}.recurrence-popup select{max-width:65%;font-size:12px}.recurrence-popup p{font-size:12px;color:var(--theme-muted)}
 .board-task>label{justify-content:flex-start}.board-task>label>span{flex:1;min-width:0}.group-controls select{flex:0 1 auto;width:auto;min-height:32px;padding:4px 8px;background:transparent}.recurrence-popup header{position:static;inset:auto;transform:none;padding:0;max-width:none;width:auto}
</style>
